SELECT count(rule_key) AS inserted_count FROM inserted LIMIT 1;

-- 적재 확인: 예시만 조회한다. 사용자 데이터는 생성/수정/삭제하지 않는다.
SELECT count(id) AS sample_count FROM public.cultural_events WHERE id IN ('e1','e2','e3','e4','e5','e6','e7','e8','e10','e11','e12','e13','e14','e15','e16','e17','e18','e19','e20','e21','e9','e22','e23','e24','e25') AND is_sample=true AND source='예시 데이터' AND user_id IS NULL LIMIT 1;
SELECT id,title,price_min,price_label FROM public.cultural_events WHERE id IN ('e1','e25') AND is_sample=true AND source='예시 데이터' AND user_id IS NULL ORDER BY id LIMIT 2;
SELECT category,count(id) AS sample_count FROM public.places WHERE id IN ('f1','f2','f3','f4','f5','f6','f7','f8','f9','f10','o1','o2','o3','o4','o5','o6','o7','o8','o9','o10') AND is_sample=true AND source='예시 데이터' AND user_id IS NULL GROUP BY category ORDER BY category LIMIT 2;
SELECT id,category,name FROM public.places WHERE id IN ('f1','o1') AND is_sample=true AND source='예시 데이터' AND user_id IS NULL ORDER BY id LIMIT 2;
SELECT count(b.rule_key) AS sample_count FROM public.event_benefits b JOIN public.cultural_events e ON e.id=b.event_id WHERE e.id IN ('e1','e2','e3','e4','e5','e6','e7','e8','e10','e11','e12','e13','e14','e15','e16','e17','e18','e19','e20','e21','e9','e22','e23','e24','e25') AND e.is_sample=true AND e.source='예시 데이터' AND e.user_id IS NULL AND b.user_id IS NULL AND b.rule_key::jsonb->>4='seed' LIMIT 1;
SELECT b.event_id,b.type,b.value,b.price_after,b.label FROM public.event_benefits b JOIN public.cultural_events e ON e.id=b.event_id WHERE e.is_sample=true AND e.source='예시 데이터' AND e.user_id IS NULL AND b.user_id IS NULL AND b.rule_key::jsonb->>4='seed' AND b.type IN ('income','multi') ORDER BY b.event_id,b.type LIMIT 4;

