    ('o9', '회'),
    ('o10', '건')
), target_places AS (
  SELECT p.id
  FROM public.places AS p
  JOIN other_price_units AS u ON u.id = p.id
  WHERE p.category = '기타'
    AND p.is_sample = true
    AND NULLIF(p.meta->>'price_unit', '') IS NULL
  ORDER BY p.id
  LIMIT 10
)
UPDATE public.places AS p
SET meta = jsonb_set(coalesce(p.meta, '{}'::jsonb), '{price_unit}', to_jsonb(u.price_unit), true)
FROM other_price_units AS u
WHERE p.id = u.id
  AND p.id IN (SELECT id FROM target_places LIMIT 10)
  AND p.category = '기타'
  AND p.is_sample = true
  AND NULLIF(p.meta->>'price_unit', '') IS NULL;
